// Текст закона для сайта (подключается при открытии раздела)
(window.LAW_DATA = window.LAW_DATA || {})["koap"] = {"items":[{"h":"Раздел 1. Общие положения"},{"h":"Глава 1. Законодательство об административном правонарушении"},{"n":"Статья 1.1","title":"Законодательство об административных правонарушениях","sub":[{"n":"1","text":"Законодательство об административных правонарушениях состоит из настоящего Кодекса и принимаемых в соответствии с ним иных нормативных правовых актов."},{"n":"2","text":"Настоящий Кодекс основывается на Конституции, определяет, какие деяния признаются административными правонарушениями, и устанавливает виды и пределы административных наказаний за их совершение."}]},{"n":"Статья 1.2","title":"Задачи законодательства об административных правонарушениях","text":"Задачами законодательства об административных правонарушениях являются защита личности, охрана прав и свобод человека и гражданина, охрана здоровья населения, защита общественной нравственности, охрана собственности и окружающей среды, обеспечение общественного порядка и безопасности дорожного движения, а также предупреждение совершения административных правонарушений."},{"n":"Статья 1.3","title":"Принцип равенства перед законом","sub":[{"n":"1","text":"Лица, совершившие административные правонарушения, равны перед законом."},{"n":"2","text":"Физические лица подлежат административной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, принадлежности к общественным объединениям, а также других обстоятельств."}]},{"n":"Статья 1.4","title":"Презумпция невиновности","sub":[{"n":"1","text":"Лицо подлежит административной ответственности только за те административные правонарушения, в отношении которых установлена его вина."},{"n":"2","text":"Лицо, в отношении которого ведется производство по делу об административном правонарушении, считается невиновным, пока его вина не будет доказана в установленном законом порядке."},{"n":"3","text":"Неустранимые сомнения в виновности лица, привлекаемого к административной ответственности, толкуются в пользу этого лица."}]},{"n":"Статья 1.5","title":"Действие законодательства во времени и пространстве","sub":[{"n":"1","text":"Лицо, совершившее административное правонарушение, подлежит ответственности на основании закона, действовавшего во время совершения административного правонарушения."},{"n":"2","text":"Закон, смягчающий или отменяющий административную ответственность за административное правонарушение либо иным образом улучшающий положение лица, совершившего правонарушение, имеет обратную силу."}]},{"n":"Статья 1.6","title":"Органы, уполномоченные рассматривать дела об административных правонарушениях","sub":[{"n":"1","text":"Дела об административных правонарушениях рассматриваются судьями, органами внутренних дел (полицией), органами прокуратуры, федеральными уполномоченными службами, а также административными комиссиями, создаваемыми при органах местного самоуправления."},{"n":"2","text":"Перечень органов и должностных лиц, уполномоченных составлять протоколы и выносить постановления по делам об административных правонарушениях, определяется настоящим Кодексом."}]},{"n":"Статья 1.7","title":"Участники производства по делу об административном правонарушении","sub":[{"n":"1","text":"Участниками производства по делу об административном правонарушении являются лицо, в отношении которого ведётся производство, потерпевший, законные представители, защитник, представитель, свидетель, понятой, эксперт, специалист, переводчик."},{"n":"2","text":"Указанные лица имеют права и несут обязанности, установленные настоящим Кодексом, и вправе заявлять ходатайства, представлять доказательства и знакомиться с материалами дела."}]},{"h":"Глава 2. Административное правонарушение и административная ответственность"},{"n":"Статья 2.1","title":"Административное правонарушение","sub":[{"n":"1","text":"Административным правонарушением признается противоправное, виновное действие (бездействие) физического или юридического лица, за которое настоящим Кодексом установлена административная ответственность."},{"n":"2","text":"Незнание законодательства не освобождает от административной ответственности лицо, совершившее противоправное деяние."}]},{"n":"Статья 2.2","title":"Формы вины","sub":[{"n":"1","text":"Административное правонарушение признается совершенным умышленно, если лицо, его совершившее, сознавало противоправный характер своего действия (бездействия), предвидело его вредные последствия и желало наступления таких последствий либо сознательно их допускало или относилось к ним безразлично."},{"n":"2","text":"Административное правонарушение признается совершенным по неосторожности, если лицо предвидело возможность наступления вредных последствий своего действия (бездействия), но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение таких последствий либо не предвидело возможности наступления таких последствий, хотя должно было и могло их предвидеть."}]},{"n":"Статья 2.3","title":"Утратила силу"},{"n":"Статья 2.4","title":"Административная ответственность должностных лиц","text":"Административной ответственности подлежит должностное лицо в случае совершения им административного правонарушения в связи с неисполнением либо ненадлежащим исполнением своих служебных (должностных) обязанностей."},{"n":"Статья 2.5","title":"Административная ответственность собственников (владельцев) транспортных средств","sub":[{"n":"1","text":"К административной ответственности за административные правонарушения в области дорожного движения привлекаются собственники (владельцы) транспортных средств."},{"n":"2","text":"Собственник (владелец) транспортного средства освобождается от административной ответственности, если в ходе проверки будет подтверждено, что в момент фиксации правонарушения транспортное средство находилось во владении или в пользовании другого лица либо выбыло из его обладания в результате противоправных действий третьих лиц."}]},{"n":"Статья 2.6","title":"Порядок и сроки уплаты административного штрафа","text":"Административный штраф должен быть уплачен лицом, привлечённым к административной ответственности, не позднее 60 дней со дня вступления постановления о наложении административного штрафа в законную силу. При неуплате административного штрафа в установленный срок — влечёт наложение административного штрафа в двукратном размере суммы неуплаченного штрафа либо административный арест на срок до 15 суток."},{"n":"Статья 2.7","title":"Правила применения обстоятельств, смягчающих и отягчающих ответственность","sub":[{"n":"1","text":"При наличии обстоятельств, смягчающих административную ответственность, размер наказания не может быть назначен выше среднего предела, установленного санкцией соответствующей статьи."},{"n":"2","text":"При наличии обстоятельств, отягчающих административную ответственность, размер наказания не может быть назначен ниже среднего предела, установленного санкцией соответствующей статьи."},{"n":"3","text":"Должностное лицо обязано мотивировать в постановлении применение или неприменение конкретных обстоятельств."}]},{"h":"Глава 3. Административное наказание"},{"n":"Статья 3.1","title":"Цели административного наказания","text":"Административное наказание является установленной государством мерой ответственности за совершение административного правонарушения и применяется в целях предупреждения совершения новых правонарушений как самим правонарушителем, так и другими лицами. Наказание не может иметь своей целью причинение физических страданий или унижение человеческого достоинства."},{"n":"Статья 3.2","title":"Возможность освобождения от ответственности при малозначительности","text":"При малозначительности совершенного административного правонарушения уполномоченное должностное лицо может освободить лицо, совершившее правонарушение, от административной ответственности и ограничиться устным замечанием."},{"n":"Статья 3.3","title":"Предупреждение","sub":[{"n":"1","text":"Предупреждение — мера административного наказания, выраженная в официальном порицании физического или юридического лица."},{"n":"2","text":"Предупреждение выносится в письменной либо устной форме с требованием прекратить противоправное поведение."},{"n":"3","text":"Неисполнение законных требований, изложенных в предупреждении, влечет административную ответственность, предусмотренную законодательством."}]},{"n":"Статья 3.4","title":"Административный штраф","sub":[{"n":"1","text":"Административный штраф является денежным взысканием, выражаемым в установленной финансовой сумме в рублях, налагаемым на граждан или должностных лиц."},{"n":"2","text":"Запрещается суммирование административных штрафов за неоднократное совершение одного и того же правонарушения в рамках одного эпизода."}]},{"n":"Статья 3.5","title":"Лишение специального права","sub":[{"n":"1","text":"Лишение специального права заключается в изъятии у физического лица права на управление транспортными средствами или права на эксплуатацию специализированного оборудования."},{"n":"2","text":"Срок лишения специального права устанавливается соответствующей статьей Особенной части настоящего Кодекса."}]},{"n":"Статья 3.6","title":"Административный арест","sub":[{"n":"1","text":"Административный арест заключается в содержании нарушителя в условиях изоляции от общества в специализированных учреждениях органа внутренних дел."},{"n":"2","text":"Срок административного ареста определяется санкцией соответствующей статьи Особенной части настоящего Кодекса."}]},{"n":"Статья 3.7","title":"Конфискация орудия совершения или предмета правонарушения","text":"Конфискацией орудия совершения или предмета административного правонарушения является принудительное безвозмездное изъятие и обращение в собственность государства вещей, не изъятых из гражданского оборота, используемых при совершении противоправного деяния."},{"h":"Глава 4. Назначение административного наказания"},{"n":"Статья 4.1","title":"Общие правила назначения административного наказания","sub":[{"n":"1","text":"Административное наказание за совершение административного правонарушения назначается в пределах, установленных законом, предусматривающим ответственность за данное правонарушение."},{"n":"2","text":"При назначении наказания учитываются характер совершенного правонарушения, личность виновного, его имущественное положение, а также обстоятельства, смягчающие и отягчающие ответственность."}]},{"n":"Статья 4.2","title":"Обстоятельства, смягчающие административную ответственность","sub":[{"n":"1","text":"добровольное прекращение противоправного поведения;"},{"n":"2","text":"раскаяние лица, совершившего административное правонарушение;"},{"n":"3","text":"добровольное возмещение причиненного ущерба или устранение причиненного вреда."}],"text":"Обстоятельствами, смягчающими административную ответственность, признаются:"},{"n":"Статья 4.3","title":"Обстоятельства, отягчающие административную ответственность","sub":[{"n":"1","text":"продолжение противоправного поведения, несмотря на требование уполномоченных лиц прекратить его;"},{"n":"2","text":"повторное совершение однородного административного правонарушения в период, когда лицо считается подвергнутым наказанию;"},{"n":"3","text":"совершение правонарушения в состоянии алкогольного или наркотического опьянения;"},{"n":"4","text":"совершение правонарушения группой лиц."}],"text":"Обстоятельствами, отягчающими административную ответственность, признаются:"},{"n":"Статья 4.4","title":"Срок, в течение которого лицо считается подвергнутым наказанию","text":"Лицо, которому назначено административное наказание, считается подвергнутым данному наказанию со дня вступления в силу постановления о назначении наказания и до истечения 12 дней (суток) после полного исполнения наказания."},{"n":"Статья 4.5","title":"Назначение наказания за совершение нескольких правонарушений","text":"При совершении лицом двух и более административных правонарушений административное наказание назначается за каждое совершенное правонарушение отдельно, за исключением случаев, предусмотренных частью 2 статьи 3.4 настоящего Кодекса."},{"n":"Статья 4.6","title":"Выбор меры административного наказания","text":"При наличии альтернативных санкций в статье Особенной части настоящего Кодекса уполномоченному должностному лицу предоставляется право выбора конкретной меры наказания с учетом тяжести совершенного проступка и личности нарушителя."},{"n":"Статья 4.7","title":"Ответственность государственного служащего","sub":[{"n":"1","text":"Государственные служащие, совершившие административные правонарушения при исполнении служебных обязанностей либо вне рабочего времени, подлежат ответственности на общих основаниях."},{"n":"2","text":"Совершение административного правонарушения при исполнении служебных обязанностей может являться основанием для проведения служебной проверки и применения дисциплинарного взыскания."}]},{"h":"Раздел 2. Особенная часть"},{"h":"Глава 5. Административные правонарушения, посягающие на права граждан"},{"n":"Статья 5.1","title":"Нарушение порядка и сроков рассмотрения обращений граждан","text":"Нарушение установленного законодательством порядка или сроков рассмотрения обращений граждан должностными лицами государственных органов, а равно оставление обращения без ответа без законных на то оснований — влечет наложение административного штрафа на должностных лиц в размере от 10 000 до 20 000 рублей."},{"n":"Статья 5.2","title":"Оскорбление","text":"Оскорбление, то есть унижение чести и достоинства другого лица, выраженное в неприличной или иной противоречащей общепринятым нормам форме, — влечет наложение административного штрафа на граждан в размере от 5 000 до 15 000 рублей."},{"n":"Статья 5.3","title":"Дискриминация","text":"Нарушение прав, свобод и законных интересов человека и гражданина в зависимости от его пола, расы, национальности, языка, происхождения, имущественного, семейного или должностного положения — влечет наложение административного штрафа в размере от 10 000 до 25 000 рублей."},{"n":"Статья 5.4","title":"Утратила силу"},{"n":"Статья 5.5","title":"Нарушение режима тайного голосования","text":"Нарушение требований о соблюдении тайны голосования при проведении официально объявленных выборов, референдумов или публичных голосований, выразившееся в осуществлении наблюдения за волеизъявлением гражданина без его согласия либо принуждении к разглашению своего выбора, — влечет наложение административного штрафа в размере от 10 000 до 30 000 рублей."},{"n":"Статья 5.6","title":"Незаконная агитация в день голосования","text":"Проведение предвыборной агитации или агитации по вопросам референдума вне агитационного периода либо в день голосования («день тишины») — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"h":"Глава 6. Административные правонарушения, посягающие на здоровье населения и общественную нравственность"},{"n":"Статья 6.1","title":"Воспрепятствование оказанию медицинской помощи","text":"Воспрепятствование в какой бы то ни было форме законной деятельности медицинского работника по оказанию медицинской помощи, если эти действия не содержат признаков уголовного преступления, — влечет наложение административного штрафа в размере от 10 000 до 15 000 рублей."},{"n":"Статья 6.2","title":"Нарушение порядка обращения за медицинской помощью","text":"Систематическое нарушение гражданами установленного порядка обращения в медицинские организации, либо нарушение установленного внутреннего режима лечебного учреждения — влечет предупреждение или наложение административного штрафа в размере от 2 000 до 5 000 рублей."},{"n":"Статья 6.3","title":"Неоказание медицинской помощи","text":"Неоказание медицинской помощи больному без уважительных причин лицом, обязанным ее оказывать в соответствии с законом или специальным правилом, если это не повлекло тяжкого вреда здоровью, — влечет наложение административного штрафа на медицинских работников или должностных лиц в размере от 15 000 до 30 000 рублей."},{"n":"Статья 6.4","title":"Отсутствие действующей медицинской книжки у сотрудника государственной организации","text":"Отсутствие действующей медицинской книжки или своевременно пройденного медицинского осмотра у сотрудника государственной организации, который в силу закона обязан проходить регулярное медицинское обследование при исполнении служебных обязанностей, — влечет наложение административного штрафа в размере от 15 000 до 25 000 рублей."},{"n":"Статья 6.5","title":"Непрохождение медицинской проверки государственной организацией","text":"Непрохождение государственной организацией обязательной медицинской проверки в установленные сроки либо прямой отказ от прохождения такой проверки — влечет наложение административного штрафа на государственную организацию в размере от 50 000 до 90 000 рублей."},{"n":"Статья 6.6","title":"Уклонение от оплаты медицинских услуг","text":"Уклонение пациента или иного лица от оплаты полученных медицинских услуг, о стоимости которых он был надлежащим образом проинформирован до их оказания, — влечет наложение административного штрафа в размере 20 000 рублей или административный арест на срок до 14 суток."},{"h":"Глава 7. Административные правонарушения в области охраны собственности и охраны окружающей среды"},{"n":"Статья 7.1","title":"Самовольное проникновение на охраняемую или частную территорию","text":"Самовольное проникновение на охраняемый в установленном порядке объект, частное домовладение или прилегающую закрытую территорию без согласия собственника или уполномоченного лица при наличии установленного ограждения или предупреждающих знаков — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей либо административный арест на срок до 3 суток."},{"n":"Статья 7.2","title":"Попытка безвозмездного проникновения в транспортное средство","text":"Попытка вскрытия или повреждения запирающих устройств (замков) транспортного средства без заведения двигателя и без цели его хищения — влечет наложение административного штрафа в размере от 10 000 до 20 000 рублей или административный арест на срок до 14 суток."},{"n":"Статья 7.3","title":"Мелкое хищение","text":"Мелкое хищение чужого имущества путем кражи, мошенничества, присвоения или растраты при отсутствии признаков уголовно наказуемого деяния — влечет наложение административного штрафа в размере от трехкратной до пятикратной стоимости похищенного имущества либо административный арест на срок до 5 суток."},{"n":"Статья 7.4","title":"Браконьерство и нарушение правил охоты","text":"Осуществление охоты или добычи ресурсов без специального разрешения (лицензии), либо в запрещенных местах, либо с превышением установленных лимитов и норм — влечет наложение административного штрафа в размере от 15 000 до 30 000 рублей с конфискацией орудий добычи."},{"n":"Статья 7.5","title":"Нарушение правил, регламентирующих рыболовство","text":"Превышение нормы вылова рыбы, использование запрещенных снастей или нарушение иных правил пользования объектами животного мира — влечет наложение административного штрафа в размере от 15 000 до 30 000 рублей с конфискацией орудий вылова."},{"n":"Статья 7.6","title":"Умышленное уничтожение или повреждение чужого имущества","text":"Умышленные уничтожение или повреждение чужого имущества, если эти действия не причинили значительного ущерба и не содержат состава уголовного преступления, — влечет наложение административного штрафа в размере от 3 000 до 10 000 рублей."},{"n":"Статья 7.7","title":"Самовольное занятие земельного участка","text":"Самовольное занятие земельного участка или использование части земельного участка без оформленных в установленном порядке правоустанавливающих документов (например, установка частных объектов, палаток, заграждений на муниципальной земле) — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 7.8","title":"Нарушение права потребителя на получение необходимой информации","sub":[{"n":"1","text":"Непредоставление или предоставление потребителю неполной либо недостоверной информации о реализуемом товаре (работе, услуге), об изготовителе, о продавце, о режиме их работы — влечёт наложение административного штрафа на должностных лиц в размере от 500 до 1 000 рублей; на юридических лиц — от 5 000 до 10 000 рублей."},{"n":"2","text":"Включение в договор условий, ущемляющих права потребителя по сравнению с правилами, установленными законом, — влечёт наложение административного штрафа на должностных лиц в размере от 1 000 до 2 000 рублей; на юридических лиц — от 10 000 до 20 000 рублей."}]},{"h":"Глава 8. Административные правонарушения, посягающие на общественный порядок и общественную безопасность"},{"n":"Статья 8.1","title":"Мелкое хулиганство","text":"Нарушение общественного порядка в общественных местах, выражающее явное неуважение к обществу, сопровождающееся нецензурной бранью, оскорбительным приставанием к гражданам либо уничтожением или повреждением чужого имущества в некрупном размере, — влечет наложение административного штрафа в размере от 3 000 до 10 000 рублей или административный арест на срок до 5 суток."},{"n":"Статья 8.2","title":"Нанесение побоев или совершение иных насильственных действий","text":"Нанесение побоев или совершение иных насильственных действий, причинивших физическую боль, но не повлекших вреда здоровью и не содержащих состава уголовного преступления, — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей либо административный арест на срок до 5 суток."},{"n":"Статья 8.3","title":"Распитие алкогольной продукции в общественных местах","text":"Потребление (распитие) алкогольной и спиртосодержащей продукции на улицах, стадионах, в скверах, парках, общественном транспорте и иных публичных местах (за исключением предприятий общественного питания) — влечет наложение административного штрафа в размере от 2 000 до 5 000 рублей."},{"n":"Статья 8.4","title":"Занятие попрошайничеством в общественных местах","text":"Навязчивое или систематическое занятие попрошайничеством на улицах, в скверах, парках, общественном транспорте и иных публичных местах — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 8.5","title":"Заведомо ложный вызов специализированных служб","text":"Заведомо ложный вызов пожарной охраны, полиции, скорой медицинской помощи или иных экстренных оперативных служб — влечет наложение административного штрафа в размере от 10 000 до 20 000 рублей."},{"n":"Статья 8.6","title":"Организация, участие или призыв к несанкционированному публичному мероприятию","text":"Организация, проведение, а равно участие или публичные призывы к участию в несанкционированных (несогласованных) митингах, демонстрациях, шествиях или пикетированиях — влечет наложение административного штрафа в размере от 15 000 до 35 000 рублей либо административный арест на срок до 7 суток."},{"n":"Статья 8.7","title":"Распространение заведомо ложных сведений, порочащих честь","text":"Распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию, при отсутствии признаков уголовного преступления — влечет наложение административного штрафа в размере от 10 000 до 20 000 рублей."},{"n":"Статья 8.8","title":"Невыполнение законных требований прокурора, следователя, дознавателя","text":"Умышленное невыполнение законных требований прокурора, следователя или дознавателя при проведении расследования, прокурорской проверки или следственных действий, а равно неявка по вызову без уважительных причин — влечет наложение административного штрафа в размере от 10 000 до 20 000 рублей."},{"n":"Статья 8.9","title":"Нарушение законодательства об исполнительном производстве","text":"Невыполнение законных требований судебного пристава-исполнителя при проведении процедур принудительного исполнения судебных актов, а равно сокрытие имущества или доходов, на которые может быть обращено взыскание, — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 8.10","title":"Нарушение правил поведения на охраняемых территориях","text":"Нарушение установленных правил поведения, фото- и видеосъемки или режима пребывания при нахождении на объектах с особым режимом доступа — влечет наложение административного штрафа в размере от 10 000 до 20 000 рублей."},{"n":"Статья 8.11","title":"Ношение масок или средств скрытия лица в общественных местах","text":"Ношение масок, балаклав или иных предметов одежды, намеренно скрывающих лицо и препятствующих идентификации личности по требованию сотрудников правоохранительных органов в общественных местах (за исключением медицинских масок при соблюдении санитарного режима), — влечет предупреждение или наложение административного штрафа в размере от 3 000 до 10 000 рублей."},{"n":"Статья 8.12","title":"Открытое ношение или демонстрация холодного оружия","text":"Открытое ношение или демонстрация холодного или конструктивно сходного с ним оружия в общественных местах без намерений его применения и без законных на то оснований — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей с конфискацией предмета."},{"n":"Статья 8.13","title":"Курение в неустановленных общественных местах","text":"Курение табачных изделий, кальянов или использование электронных испарительных систем в зонах действия запрета на курение (территории больниц, образовательных учреждений, госорганов, остановки общественного транспорта) — влечет наложение административного штрафа в размере от 1 000 до 3 000 рублей."},{"n":"Статья 8.14","title":"Нарушение требований режима особых правовых состояний","text":"Нарушение правил и предписаний, установленных органами власти в рамках режимов Чрезвычайного Положения, Военного Положения, Контртеррористической операции или Комендантского часа, а равно перемещение без спецпропусков в комендантский час — влечет наложение административного штрафа в размере от 15 000 до 30 000 рублей или административный арест на срок до 10 суток."},{"n":"Статья 8.15","title":"Появление в общественных местах в состоянии опьянения","text":"Появление на улицах, стадионах, в скверах, парках, в транспортном средстве общего пользования или в других общественных местах в состоянии опьянения, оскорбляющем человеческое достоинство и общественную нравственность, — влечет наложение административного штрафа в размере от 2 000 до 5 000 рублей или административный арест на срок до 5 суток."},{"n":"Статья 8.16","title":"Нарушение тишины и покоя граждан (Нарушение режима тишины)","text":"Совершение действий, нарушающих тишину и покой граждан в ночное время (с 23:00 до 07:00), путем использования звуковоспроизводящих устройств на повышенной громкости, громкого пения, свиста, использования пиротехники или проведения ремонтных работ, — влечет предупреждение или наложение административного штрафа в размере от 2 000 до 5 000 рублей."},{"n":"Статья 8.17","title":"Умышленная порча или уничтожение удостоверения личности","text":"Умышленные уничтожение или порча документа, удостоверяющего личность гражданина (паспорта), либо небрежное хранение, повлекшее его утрату, — влечет предупреждение или наложение административного штрафа в размере от 1 000 до 3 000 рублей."},{"n":"Статья 8.18","title":"Проживание или пребывание гражданина без удостоверения личности","text":"Проживание или нахождение гражданина на территории без документа, удостоверяющего личность (паспорта), либо по недействительному документу — влечет предупреждение или наложение административного штрафа в размере от 2 000 до 5 000 рублей."},{"n":"Статья 8.19","title":"Проведение несанкционированных спортивных или экстремальных мероприятий (Уличные гонки)","text":"Организация либо участие в несанкционированных массовых автомобильных, мотоциклетных или иных спортивных соревнованиях (уличных гонках) на дорогах общего пользования или на прилегающих территориях, создающих угрозу безопасности граждан, — влечет наложение административного штрафа на участников в размере 10 000 рублей; на организаторов — 25 000 рублей либо административный арест на срок до 5 суток."},{"n":"Статья 8.20","title":"Осуществление предпринимательской деятельности без лицензии или разрешения","text":"Осуществление предпринимательской деятельности (торговля, оказание услуг, частный сыск, охранная деятельность) без специального разрешения (лицензии), если такое разрешение обязательно, — влечет наложение административного штрафа в размере от 10 000 до 25 000 рублей с конфискацией произведенной продукции и орудий производства."},{"n":"Статья 8.21","title":"Продажа или передача алкогольной и спиртосодержащей продукции несовершеннолетним","text":"Розничная продажа или передача алкогольной продукции либо табачных изделий несовершеннолетнему лицом, достигшим совершеннолетия, — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 8.22","title":"Мелкое вымогательство","text":"Требование передачи чужого имущества или права на имущество под угрозой применения незначительного насилия, разглашения сведений или повреждения имущества, при отсутствии состава уголовного преступления, — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей либо административный арест на срок до 5 суток."},{"n":"Статья 8.23","title":"Навязывание потребителю дополнительных товаров или услуг","text":"Обусловливание приобретения одних товаров (работ, услуг) обязательным приобретением иных товаров (работ, услуг), а равно обусловливание оказания услуги обязательным приобретением товара, не предусмотренного законом — влечёт наложение административного штрафа на должностных лиц в размере до 150 000 рублей; на юридических лиц — до 500 000 рублей."},{"h":"Глава 9. Административные правонарушения в области дорожного движения"},{"n":"Статья 9.1","title":"Управление ТС водителем, не имеющим при себе документов","text":"Управление транспортным средством водителем, не имеющим при себе водительского удостоверения или регистрационных документов на транспортное средство, — влечет предупреждение или наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.2","title":"Отказ от предъявления документов по требованию сотрудника ГИБДД","text":"Отказ или уклонение водителя от передачи для проверки документов, предусмотренных Правилами дорожного движения, по законному требованию сотрудника полиции, — влечет наложение административного штрафа в размере 5 000 рублей."},{"n":"Статья 9.3","title":"Управление ТС, не зарегистрированным в установленном порядке","text":"Управление транспортным средством, не прошедшим государственный учет и регистрацию в органах ГИБДД в установленные сроки, — влечет наложение административного штрафа в размере от 3 000 до 5 000 рублей."},{"n":"Статья 9.4","title":"Управление ТС с нарушением требований к тонировке стекол","text":"Управление транспортным средством, на котором установлены стекла (в том числе покрытые пленками), светопропускание которых не соответствует требованиям технического регламента о безопасности, — влечет наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.5","title":"Управление ТС при наличии технических неисправностей","text":"Управление транспортным средством с неисправностями рулевого управления, тормозной системы, отсутствием кузовных элементов (бамперов, дверей) или с поврежденной световой оптикой — влечет наложение административного штрафа в размере 2 000 рублей."},{"n":"Статья 9.6","title":"Нарушение ПДД пешеходами, велосипедистами или водителями СИМ","text":"Переход проезжей части в неположенном месте, движение на запрещающий сигнал светофора или иное нарушение ПДД пешеходом, велосипедистом или лицом, управляющим средством индивидуальной мобильности, — влечет предупреждение или наложение административного штрафа в размере 1 000 рублей."},{"n":"Статья 9.7","title":"Нарушение правил посадки или высадки пассажиров","text":"Посадка или высадка пассажиров со стороны проезжей части дороги либо до полной остановки транспортного средства — влечет наложение административного штрафа в размере 1 500 рублей."},{"n":"Статья 9.8","title":"Игнорирование водителем требования об остановке ТС","text":"Невыполнение законного требования сотрудника полиции (ГИБДД) об остановке транспортного средства — влечет наложение административного штрафа в размере 10 000 рублей либо лишение права управления ТС на срок до 1 месяца."},{"n":"Статья 9.9","title":"Несоблюдение требований дорожных знаков или разметки","text":"Несоблюдение требований, предписанных дорожными знаками или разметкой проезжей части дороги, — влечет предупреждение или наложение административного штрафа в размере 2 000 рублей."},{"n":"Статья 9.10","title":"Нарушение правил применения спецсигналов","text":"Использование приоритета в движении при следовании с включенными проблесковыми маячками и звуковым сигналом водителем транспортного средства оперативных служб, не убедившимся в безопасности данного маневра, — влечет наложение административного штрафа в размере 5 000 рублей."},{"n":"Статья 9.11","title":"Нарушение правил использования аварийных сигналов","text":"Нарушение правил использования световой аварийной сигнализации и знака аварийной остановки при вынужденной остановке или ДТП — влечет предупреждение или наложение административного штрафа в размере 1 000 рублей."},{"n":"Статья 9.12","title":"Управление ТС с выключенными фарами","text":"Управление транспортным средством в темное время суток, в условиях недостаточной видимости или в туннелях без включенных фар ближнего света или дневных ходовых огней — влечет наложение административного штрафа в размере 1 500 рублей."},{"n":"Статья 9.13","title":"Нарушение правил пользования звуковым сигналом","text":"Подача звукового сигнала в пределах населенных пунктов в случаях, не предусмотренных ПДД (кроме случаев предотвращения ДТП), — влечет наложение административного штрафа в размере 1 000 рублей."},{"n":"Статья 9.14","title":"Проезд на запрещающий сигнал светофора или регулировщика","text":"Проезд на запрещающий (красный или желтый) сигнал светофора либо на запрещающий жест регулировщика на регулируемых перекрестках и пешеходных переходах — влечет наложение административного штрафа в размере 5 000 рублей."},{"n":"Статья 9.15","title":"Невыполнение требования остановиться перед стоп-линией","text":"Невыполнение требования ПДД остановиться перед стоп-линией (знаком «Стоп») при запрещающем сигнале светофора — влечет наложение административного штрафа в размере 1 500 рублей."},{"n":"Статья 9.16","title":"Невыполнение требований о подаче сигнала указателями поворота","text":"Невыполнение требования ПДД подать сигнал световым указателем поворота перед началом движения, перестроением, поворотом, разворотом или остановкой — влечет предупреждение или наложение административного штрафа в размере 1 000 рублей."},{"n":"Статья 9.17","title":"Непредоставление преимущества при перестроении","text":"Непредоставление преимущества в движении транспортному средству, пользующемуся первоочередным правом движения при маневре или перестроении, — влечет наложение административного штрафа в размере 2 000 рублей."},{"n":"Статья 9.18","title":"Поворот из полосы, не предназначенной для маневра","text":"Поворот налево, направо или разворот из полосы движения, не предназначенной для совершения данного маневра согласно разметке или знакам, — влечет наложение административного штрафа в размере 2 500 рублей."},{"n":"Статья 9.19","title":"Нарушение правил совершения разворота или поворота","text":"Совершение поворота или разворота в нарушение требований дорожных знаков или разметки проезжей части — влечет наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.20","title":"Движение по полосе встречного движения","text":"Движение во встречном направлении по дороге с односторонним движением либо выезд в нарушение ПДД на полосу встречного движения — влечет наложение административного штрафа в размере 10 000 рублей или лишение права управления ТС."},{"n":"Статья 9.21","title":"Повреждение дорог, дорожных сооружений или технических средств","text":"Повреждение автодорог, железнодорожных переездов, дорожных знаков, светофоров или иных технических средств организации движения — влечет наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 9.22","title":"Выезд на встречную полосу, повлекший создание аварийной ситуации","text":"Выезд в нарушение ПДД на полосу встречного движения при совершении обгона или объезда, вынудивший других участников движения резко изменить скорость или направление движения, — влечет наложение административного штрафа в размере 10 000 рублей либо лишение права управления ТС."},{"n":"Статья 9.23","title":"Движение по левым полосам при свободных правых","text":"Движение по крайним левым полосам движения вне населенных пунктов или на автомагистралях при свободных правых полосах — влечет наложение административного штрафа в размере 1 500 рублей."},{"n":"Статья 9.24","title":"Движение по прерывистым линиям разметки","text":"Длительное движение по прерывистым линиям разметки без цели перестроения — влечет предупреждение или наложение административного штрафа в размере 1 000 рублей."},{"n":"Статья 9.25","title":"Движение по обочинам, тротуарам и разделительным полосам","text":"Движение транспортных средств по обочинам, тротуарам, пешеходным дорожкам или разделительным полосам — влечет наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.26","title":"Несоблюдение дистанции и бокового интервала","text":"Несоблюдение безопасной дистанции до движущегося впереди ТС либо бокового интервала, обеспечивающего безопасность движения, — влечет предупреждение или наложение административного штрафа в размере 1 500 рублей."},{"n":"Статья 9.27","title":"Обгон и непредоставление преимущества ТС со специальными сигналами","text":"Совершение обгона ТС оперативных служб с включенными синим (красным) проблесковым маячком и специальным звуковым сигналом либо непредоставление ему преимущества в движении — влечет наложение административного штрафа в размере 5 000 рублей или лишение права управления ТС."},{"n":"Статья 9.28","title":"Обгон в запрещенных местах","text":"Совершение обгона транспортного средства на пешеходных переходах, железнодорожных переездах, мостах, эстакадах и в конце подъемов — влечет наложение административного штрафа в размере 5 000 рублей."},{"n":"Статья 9.29","title":"Препятствование обгону","text":"Препятствование обгону путем повышения скорости движения или иными действиями водителя обгоняемого ТС — влечет наложение административного штрафа в размере 2 000 рублей."},{"n":"Статья 9.30","title":"Остановка или стоянка на пешеходном переходе","text":"Остановка или стоянка транспортных средств на пешеходном переходе и ближе 5 метров перед ним — влечет наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.31","title":"Остановка или стоянка в местах остановки маршрутных ТС","text":"Остановка или стоянка транспортных средств в местах остановки маршрутных ТС либо ближе 15 метров от них — влечет наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.32","title":"Нарушение правил остановки/стоянки, повлекшее создание препятствий","text":"Остановка или стоянка ТС на проезжей части, повлекшая создание препятствий для движения других транспортных средств или оперативных служб, — влечет наложение административного штрафа в размере 4 000 рублей и принудительную эвакуацию ТС."},{"n":"Статья 9.33","title":"Нарушение иных правил остановки или стоянки","text":"Нарушение иных правил остановки или стоянки ТС, не предусмотренных статьями 9.30–9.32 настоящего Кодекса, — влечет предупреждение или наложение административного штрафа в размере 1 500 рублей."},{"n":"Статья 9.34","title":"Нарушение правил проезда перекрестков","text":"Нарушение правил очередности проезда перекрестков, не повлекшее создания аварийной ситуации, — влечет наложение административного штрафа в размере 2 000 рублей."},{"n":"Статья 9.35","title":"Управление ТС водителем, находящимся в состоянии опьянения","text":"Управление транспортным средством водителем, находящимся в состоянии алкогольного, наркотического или иного токсического опьянения, а равно отказ от прохождения освидетельствования — влечет наложение административного штрафа в размере 15 000 рублей с лишением права управления ТС или административный арест на срок до 5 суток."},{"n":"Статья 9.36","title":"Парковка на газонах и элементах благоустройства","text":"Размещение (остановка или стоянка) транспортных средств на газонах, зеленых насаждениях, детских или спортивных площадках — влечет наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.37","title":"Управление ТС с нечитаемыми или видоизмененными государственными номерами","text":"Управление транспортным средством с видоизмененными, скрытыми с применением маскировочных устройств либо отсутствующими государственными регистрационными знаками — влечет наложение административного штрафа в размере 5 000 рублей или лишение права управления ТС."},{"n":"Статья 9.38","title":"Превышение установленной скорости движения","sub":[{"n":"1","text":"Превышение установленной скорости движения транспортного средства на величину от 20 до 40 километров в час — влечет наложение административного штрафа в размере 1 000 рублей."},{"n":"2","text":"Превышение установленной скорости движения транспортного средства на величину от 40 до 60 километров в час — влечет наложение административного штрафа в размере 2 500 рублей."},{"n":"3","text":"Превышение установленной скорости движения транспортного средства на величину более 60 километров в час — влечет наложение административного штрафа в размере 5 000 рублей или лишение права управления транспортными средствами."}]},{"n":"Статья 9.39","title":"Нарушение правил перевозки людей (Опасная транспортировка)","text":"Перевозка людей вне кабины автомобиля (на капоте, багажнике, крыше, в открытом кузове грузового автомобиля), а равно превышение количества перевозимых людей над предусмотренным технической характеристикой ТС — влечет наложение административного штрафа в размере 3 000 рублей."},{"n":"Статья 9.40","title":"Нарушение правил движения через железнодорожные пути","text":"Пересечение железнодорожного пути вне железнодорожного переезда, выезд на железнодорожный переезд при закрытом или закрывающемся шлагбауме либо при запрещающем сигнале светофора — влечет наложение административного штрафа в размере 5 000 рублей или лишение права управления ТС."},{"n":"Статья 9.41","title":"Движение на транспортном средстве по пешеходным зонам и тротуарам","text":"Движение транспортных средств по пешеходным дорожкам, тротуарам, пешеходным зонам или велосипедным дорожкам в нарушение ПДД — влечет наложение административного штрафа в размере 3 500 рублей."},{"n":"Статья 9.42","title":"Оставление места дорожно-транспортного происшествия","text":"Оставление водителем в нарушение Правил дорожного движения места дорожно-транспортного происшествия, участником которого он являлся (при отсутствии признаков уголовного преступления), — влечет лишение права управления транспортными средствами либо административный арест на срок до 5 суток."},{"n":"Статья 9.43","title":"Оказание помех движению транспортных средств оперативных и экстренных служб стоящим ТС","text":"Парковка или остановка транспортного средства, блокирующая проезд или выезд специальной техники и спецтранспорта (пожарные машины, скорая помощь, полиция) из мест постоянной дислокации или на месте вызова, — влечет наложение административного штрафа в размере 5 000 рублей и принудительную эвакуацию ТС."},{"n":"Статья 9.44","title":"Управление ТС водителем, не пристегнутым ремнем безопасности","text":"Управление транспортным средством водителем, не пристегнутым ремнем безопасности, а равно перевозка пассажиров, не пристегнутых ремнями безопасности, если конструкцией ТС предусмотрены ремни безопасности, — влечет наложение административного штрафа в размере 1 500 рублей."},{"n":"Статья 9.45","title":"Нарушение правил использования телефона водителем во время движения","text":"Пользование водителем во время движения транспортного средства телефоном, не оборудованным техническим устройством, позволяющим вести переговоры без использования рук, — влечет наложение административного штрафа в размере 2 000 рублей."},{"n":"Статья 9.46","title":"Опасное вождение","text":"Опасное вождение, выражающееся в неоднократном совершении одного или нескольких последовательных действий, создающих угрозу возникновения аварийной ситуации (перестроение при интенсивном движении при всех занятых полосах, невыполнение требования уступить дорогу, резкое торможение перед другим ТС), — влечет наложение административного штрафа в размере 5 000 рублей."},{"n":"Статья 9.47","title":"Передача управления транспортным средством лицу, не имеющему права управления либо находящемуся в состоянии опьянения","text":"Передача управления транспортным средством лицу, заведомо не имеющему права управления ТС либо лишенному такого права, а равно лицу, находящемуся в состоянии опьянения, — влечет наложение административного штрафа в размере 15 000 рублей."},{"n":"Статья 9.48","title":"Нарушение правил перевозки опасных, крупногабаритных или тяжеловесных грузов","text":"Перевозка опасных грузов (включая нелицензированные перевозки взрывчатых или горючих веществ), а равно крупногабаритных грузов без специального разрешения или с отклонением от согласованного маршрута — влечет наложение административного штрафа в размере от 10 000 до 25 000 рублей."},{"n":"Статья 9.49","title":"Управление ТС, оборудованным специальными световыми или звуковыми сигналами без специального разрешения","text":"Установка на транспортном средстве без соответствующего разрешения устройств для подачи специальных световых или звуковых сигналов (за исключением охранной сигнализации), а равно управление таким ТС — влечет наложение административного штрафа в размере 10 000 рублей с конфискацией указанных устройств."},{"n":"Статья 9.50","title":"Нарушение правил учебной езды","text":"Нарушение правил учебной езды водителем-инструктором либо обучаемым (проведение обучения лицами, не имеющими на то специального права, либо в запрещенных ПДД местах) — влечет наложение административного штрафа в размере от 2 000 до 5 000 рублей."},{"h":"Глава 10. Административные правонарушения в области этики и на воздушном транспорте"},{"n":"Статья 10.1","title":"Неисполнение требований к внешнему виду","text":"Неисполнение или ненадлежащее исполнение сотрудником государственной организации установленных дресс-кодом или уставом требований к внешнему виду и ношению форменного обмундирования при исполнении обязанностей — влечет предупреждение или наложение административного штрафа на должностных лиц в размере от 3 000 до 10 000 рублей."},{"n":"Статья 10.2","title":"Неисполнение требований этики работников государственных организаций","text":"Нарушение сотрудником государственной организации установленных этических норм, проявление хамства, некорректного поведения или провоцирование конфликтов с гражданами при исполнении служебных обязанностей — влечет наложение административного штрафа на служащих в размере от 5 000 до 15 000 рублей."},{"n":"Статья 10.3","title":"Взлет, движение или посадка воздушного судна без уведомления","text":"Осуществление взлета, посадки или маневрирования на воздушном судне без предварительного уведомления диспетчерских служб или согласования с правоохранительными органами — влечет наложение административного штрафа в размере от 15 000 до 30 000 рублей с приостановлением права пилотирования."},{"n":"Статья 10.4","title":"Нарушение правил пользования воздушным пространством","text":"Опасное маневрирование, снижение ниже допустимой высоты над жилыми зонами либо полет над закрытыми и охраняемыми территориями без соответствующего разрешения — влечет наложение административного штрафа в размере от 20 000 до 40 000 рублей."},{"h":"Глава 11. Административные правонарушения в области документооборота и государственного учета"},{"n":"Статья 11.1","title":"Нарушение правил ведения служебной документации","text":"Небрежное, искаженное или неполное заполнение обязательной процессуальной или ведомственной документации должностным лицом органа власти при ведении реестров, протоколов или баз данных — влечет предупреждение или наложение административного штрафа на должностных лиц в размере от 5 000 до 15 000 рублей."},{"n":"Статья 11.2","title":"Использование недействительных документов","text":"Предоставление должностным лицам заведомо недостоверных, просроченных или видоизмененных справок, лицензий и иных документов при отсутствии признаков уголовного состава подлога — влечет наложение административного штрафа в размере от 10 000 до 25 000 рублей."},{"n":"Статья 11.3","title":"Уклонение от прохождения обязательной государственной регистрации","text":"Уклонение от подачи сведений или регистрационных данных в органы государственной власти в случаях, когда такая обязанность прямо предусмотрена действующим законодательством, — влечет наложение административного штрафа на граждан в размере от 5 000 до 10 000 рублей; на юридических лиц — от 20 000 до 40 000 рублей."},{"h":"Глава 12. Административные правонарушения в области связи и информации"},{"n":"Статья 12.1","title":"Реклама средств обхода блокировок доступа к информационным ресурсам","text":"Распространение рекламы технических средств и способов, позволяющих получить доступ к информационным ресурсам, доступ к которым ограничен уполномоченными органами — влечёт наложение административного штрафа на юридических лиц в размере до 500 000 рублей."},{"n":"Статья 12.2","title":"Умышленный поиск и получение доступа к запрещённым экстремистским материалам","text":"Умышленный поиск в информационно-телекоммуникационных сетях материалов, включённых в опубликованный федеральный список экстремистских материалов, и получение к ним доступа — влечёт наложение административного штрафа на граждан в размере до 5 000 рублей."},{"h":"Глава 13. Административные правонарушения в области защиты прав потребителей"},{"n":"Статья 13.1","title":"Нарушение права потребителя на информацию","text":"Непредоставление или предоставление потребителю неполной либо недостоверной информации о реализуемом товаре (работе, услуге), об изготовителе, о продавце, о режиме их работы — влечёт наложение административного штрафа на должностных лиц в размере от 500 до 1 000 рублей; на юридических лиц — от 5 000 до 10 000 рублей."},{"n":"Статья 13.2","title":"Включение в договор условий, ущемляющих права потребителя","text":"Включение в договор условий, ущемляющих права потребителя по сравнению с правилами, установленными законом — влечёт наложение административного штрафа на должностных лиц в размере от 1 000 до 2 000 рублей; на юридических лиц — от 10 000 до 20 000 рублей."},{"n":"Статья 13.3","title":"Навязывание потребителю дополнительных товаров или услуг","text":"Обусловливание приобретения одних товаров (работ, услуг) обязательным приобретением иных товаров (работ, услуг), а равно обусловливание оказания услуги обязательным приобретением товара, не предусмотренного законом — влечёт наложение административного штрафа на должностных лиц в размере до 150 000 рублей; на юридических лиц — до 500 000 рублей."},{"h":"Глава 14. Административные правонарушения против порядка управления"},{"n":"Статья 14.1","title":"Незаконное ношение форменной одежды со знаками различия, с символикой государственных военизированных организаций, правоохранительных или контролирующих органов","text":"Ношение форменной одежды со знаками различия, с символикой государственных органов или силовых структур лицом, не имеющим на то законного права, — влечет наложение административного штрафа в размере от 5 000 до 10 000 рублей с конфискацией форменной одежды."},{"n":"Статья 14.2","title":"Оскорбление представителя власти","text":"Публичное оскорбление представителя власти при исполнении им должностных обязанностей или в связи с их исполнением, выраженное в неприличной или иной противоречащей общепринятым нормам форме, — влечёт наложение административного штрафа в размере от 10 000 до 30 000 рублей или административный арест на срок до 10 суток."},{"n":"Статья 14.3","title":"Угроза применения насилия в отношении представителя власти","text":"Угроза применения насилия в отношении представителя власти или его близких в связи с исполнением им должностных обязанностей, при отсутствии признаков уголовного преступления, — влечёт наложение административного штрафа в размере от 15 000 до 30 000 рублей или административный арест на срок до 15 суток."},{"n":"Статья 14.4","title":"Невыполнение законных требований прокурора, следователя, дознавателя","text":"Умышленное невыполнение законных требований прокурора, следователя или дознавателя при проведении расследования, прокурорской проверки или следственных действий, а равно неявка по вызову без уважительных причин — влечёт наложение административного штрафа в размере от 10 000 до 20 000 рублей."},{"n":"Статья 14.5","title":"Невыполнение законных требований судебного пристава-исполнителя","text":"Невыполнение законных требований судебного пристава-исполнителя при проведении процедур принудительного исполнения судебных актов, а равно сокрытие имущества или доходов, на которые может быть обращено взыскание, — влечёт наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 14.6","title":"Заведомо ложный вызов экстренных служб","text":"Заведомо ложный вызов пожарной охраны, полиции, скорой медицинской помощи или иных экстренных оперативных служб — влечёт наложение административного штрафа в размере от 10 000 до 20 000 рублей."},{"n":"Статья 14.7","title":"Неповиновение законному распоряжению или требованию сотрудника органа власти","text":"Неповиновение законному распоряжению или требованию сотрудника полиции, Росгвардии, ФСБ, военнослужащего, а равно иного должностного лица органа государственной власти при исполнении им служебных обязанностей, а также воспрепятствование исполнению им служебных обязанностей — влечёт наложение административного штрафа в размере от 10 000 до 25 000 рублей или административный арест на срок до 15 суток."},{"n":"Статья 14.8","title":"Предоставление заведомо недостоверных сведений должностному лицу","text":"Предоставление должностному лицу органа государственной власти заведомо недостоверных, просроченных или видоизменённых справок, лицензий, удостоверений и иных документов при отсутствии признаков уголовного преступления — влечёт наложение административного штрафа в размере от 10 000 до 25 000 рублей."},{"n":"Статья 14.9","title":"Уклонение от прохождения обязательной государственной регистрации","text":"Уклонение от подачи сведений или регистрационных данных в органы государственной власти в случаях, когда такая обязанность прямо предусмотрена действующим законодательством, — влечёт наложение административного штрафа на граждан в размере от 5 000 до 10 000 рублей; на юридических лиц — от 20 000 до 40 000 рублей."},{"n":"Статья 14.10","title":"Нарушение правил ведения служебной документации","text":"Небрежное, искажённое или неполное заполнение обязательной процессуальной или ведомственной документации должностным лицом органа власти при ведении реестров, протоколов или баз данных — влечёт предупреждение или наложение административного штрафа на должностных лиц в размере от 5 000 до 15 000 рублей."},{"n":"Статья 14.11","title":"Самовольное присвоение властных полномочий","text":"Самовольное присвоение себе звания или должности представителя власти, а равно совершение действий, явно выходящих за пределы предоставленных полномочий, при отсутствии признаков уголовного преступления, — влечёт наложение административного штрафа в размере от 15 000 до 30 000 рублей или административный арест на срок до 10 суток."},{"n":"Статья 14.12","title":"Воспрепятствование деятельности органов государственной власти","text":"Воспрепятствование законной деятельности органов государственной власти, органов местного самоуправления, избирательных комиссий, а равно создание помех в работе указанных органов — влечёт наложение административного штрафа в размере от 10 000 до 20 000 рублей или административный арест на срок до 7 суток."},{"n":"Статья 14.13","title":"Нарушение порядка проведения публичных слушаний и собраний","text":"Нарушение установленного порядка организации или проведения публичных слушаний, собраний, конференций граждан, а равно воспрепятствование их проведению — влечёт наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 14.14","title":"Неповиновение законному требованию депутата или должностного лица","text":"Неповиновение законному требованию депутата, члена выборного органа местного самоуправления, должностного лица органа государственной власти при исполнении ими служебных обязанностей — влечёт наложение административного штрафа в размере от 5 000 до 15 000 рублей."},{"n":"Статья 14.15","title":"Незаконное использование государственной символики","text":"Незаконное использование Государственного флага, Государственного герба, Государственного гимна Российской Федерации, а равно символики органов государственной власти лицом, не имеющим на то права, — влечёт наложение административного штрафа в размере от 5 000 до 10 000 рублей с конфискацией предмета правонарушения."},{"n":"Статья 14.16","title":"Нарушение правил воинского учёта","text":"Неявка по повестке военного комиссариата без уважительных причин, а равно непредставление сведений об изменении учётных данных — влечёт наложение административного штрафа в размере от 10 000 до 30 000 рублей."},{"n":"Статья 14.17","title":"Непредставление сведений в государственные информационные системы","text":"Непредставление или несвоевременное представление сведений в государственные информационные системы, обязательность представления которых установлена законом, — влечёт наложение административного штрафа на должностных лиц в размере от 10 000 до 20 000 рублей; на юридических лиц — от 50 000 до 100 000 рублей."},{"n":"Статья 14.18","title":"Нарушение режима Государственной границы","text":"Нарушение правил пересечения Государственной границы, а равно нахождение в пограничной зоне без документов, удостоверяющих личность, — влечёт наложение административного штрафа в размере от 10 000 до 25 000 рублей или административный арест на срок до 15 суток."},{"n":"Статья 14.19","title":"Нарушение правил оборота служебного оружия","text":"Нарушение правил ношения, хранения или использования служебного оружия должностным лицом, имеющим на то право, — влечёт наложение административного штрафа в размере от 10 000 до 20 000 рублей с конфискацией оружия или без таковой."},{"n":"Статья 14.20","title":"Неисполнение требований по гражданской обороне","text":"Неисполнение должностным лицом обязанностей по организации и проведению мероприятий гражданской обороны, а равно воспрепятствование их проведению — влечёт наложение административного штрафа в размере от 10 000 до 20 000 рублей."},{"h":"Глава 15. Производство по делам об административных правонарушениях"},{"n":"Статья 15.1","title":"Задачи и принципы производства по делам об административных правонарушениях","sub":[{"n":"1","text":"Производство по делам об административных правонарушениях осуществляется в целях всестороннего, полного, объективного и своевременного выяснения обстоятельств каждого дела, разрешения его в соответствии с законом, обеспечения исполнения вынесенного постановления, а также выявления причин и условий, способствовавших совершению административных правонарушений."},{"n":"2","text":"Производство осуществляется на основе принципов законности, равенства всех перед законом, презумпции невиновности, состязательности сторон, гласности, независимости судей и должностных лиц, рассматривающих дело."},{"n":"3","text":"Никто не может быть подвергнут административному наказанию иначе как на основаниях и в порядке, установленных настоящим Кодексом."}]},{"n":"Статья 15.2","title":"Обстоятельства, исключающие производство по делу","sub":[{"n":"1","text":"отсутствие события административного правонарушения;"},{"n":"2","text":"отсутствие состава административного правонарушения;"},{"n":"3","text":"действие лица в состоянии крайней необходимости;"},{"n":"4","text":"издание акта амнистии, устраняющего применение административного наказания;"},{"n":"5","text":"отмена закона, устанавливающего административную ответственность;"},{"n":"6","text":"истечение срока давности привлечения к административной ответственности;"},{"n":"7","text":"наличие по тому же факту постановления о назначении наказания либо о прекращении производства;"},{"n":"8","text":"смерть физического лица, в отношении которого ведётся производство."}],"text":"Производство по делу об административном правонарушении не может быть начато, а начатое подлежит прекращению при наличии хотя бы одного из следующих обстоятельств:"},{"n":"Статья 15.3","title":"Обстоятельства, подлежащие выяснению по делу","sub":[{"n":"1","text":"По делу об административном правонарушении выяснению подлежат:"},{"n":"•","text":"наличие события административного правонарушения;"},{"n":"•","text":"лицо, совершившее противоправные действия (бездействие);"},{"n":"•","text":"виновность лица в совершении правонарушения;"},{"n":"•","text":"обстоятельства, смягчающие и отягчающие ответственность;"},{"n":"•","text":"характер и размер причинённого ущерба;"},{"n":"•","text":"обстоятельства, исключающие производство по делу;"},{"n":"•","text":"иные обстоятельства, имеющие значение для правильного разрешения дела."},{"n":"2","text":"Доказательствами являются любые фактические данные, на основании которых устанавливается наличие или отсутствие события правонарушения, виновность лица, а также иные обстоятельства, имеющие значение для дела."}]},{"n":"Статья 15.4","title":"Лица, участвующие в производстве по делу","sub":[{"n":"1","text":"Лицами, участвующими в производстве, являются:"},{"n":"•","text":"лицо, в отношении которого ведётся производство;"},{"n":"•","text":"потерпевший;"},{"n":"•","text":"законные представители;"},{"n":"•","text":"защитник и представитель;"},{"n":"•","text":"свидетель;"},{"n":"•","text":"понятой;"},{"n":"•","text":"эксперт;"},{"n":"•","text":"специалист;"},{"n":"•","text":"переводчик."},{"n":"2","text":"Лицо, в отношении которого ведётся производство, вправе знакомиться со всеми материалами дела, давать объяснения, представлять доказательства, заявлять ходатайства и отводы, пользоваться помощью защитника, обжаловать постановление."}]},{"n":"Статья 15.5","title":"Отводы судье, должностному лицу, эксперту, переводчику","sub":[{"n":"1","text":"Судья, должностное лицо, эксперт, специалист или переводчик не могут участвовать в производстве, если они:"},{"n":"•","text":"являются родственником лица, в отношении которого ведётся производство, потерпевшего или их представителей;"},{"n":"•","text":"лично заинтересованы в исходе дела;"},{"n":"•","text":"находятся в служебной или иной зависимости от лица, участвующего в деле."},{"n":"2","text":"При наличии указанных обстоятельств лицо обязано заявить самоотвод. По тем же основаниям отвод может быть заявлен лицом, участвующим в деле."}]},{"n":"Статья 15.6","title":"Поводы и основания к возбуждению дела","sub":[{"n":"1","text":"Поводами к возбуждению дела являются:"},{"n":"•","text":"непосредственное обнаружение должностным лицом достаточных данных о правонарушении;"},{"n":"•","text":"материалы из правоохранительных органов, государственных органов, общественных объединений;"},{"n":"•","text":"сообщения и заявления физических и юридических лиц, а также сообщения в СМИ."},{"n":"2","text":"Дело считается возбуждённым с момента составления протокола либо вынесения определения о возбуждении дела."}]},{"n":"Статья 15.7","title":"Протокол об административном правонарушении","sub":[{"n":"1","text":"О совершении правонарушения составляется протокол. В протоколе указываются:"},{"n":"•","text":"дата и место составления;"},{"n":"•","text":"должность, фамилия и инициалы составившего;"},{"n":"•","text":"сведения о лице, в отношении которого возбуждено дело;"},{"n":"•","text":"место, время и событие правонарушения;"},{"n":"•","text":"статья настоящего Кодекса;"},{"n":"•","text":"объяснение лица;"},{"n":"•","text":"сведения о свидетелях и потерпевших;"},{"n":"•","text":"иные сведения, необходимые для разрешения дела."},{"n":"2","text":"Протокол подписывается составившим его должностным лицом и лицом, в отношении которого возбуждено дело. Копия протокола вручается лицу под расписку."}]},{"n":"Статья 15.8","title":"Административное задержание","sub":[{"n":"1","text":"Административное задержание — кратковременное ограничение свободы, применяемое в исключительных случаях для обеспечения правильного и своевременного рассмотрения дела."},{"n":"2","text":"Об задержании составляется протокол с указанием даты, времени, места, оснований и мотива задержания, сведений о задержанном, времени задержания и освобождения."},{"n":"3","text":"Срок задержания не должен превышать три часа. Если дело влечёт административный арест, срок может составлять до сорока восьми часов."},{"n":"4","text":"Задержанный вправе сообщить о задержании близким родственникам и защитнику."}]},{"n":"Статья 15.9","title":"Меры обеспечения производства по делу","sub":[{"n":"1","text":"В целях пресечения правонарушения, установления личности, составления протокола и обеспечения рассмотрения дела применяются:"},{"n":"•","text":"доставление;"},{"n":"•","text":"административное задержание;"},{"n":"•","text":"личный досмотр, досмотр вещей;"},{"n":"•","text":"досмотр транспортного средства;"},{"n":"•","text":"изъятие документов и предметов;"},{"n":"•","text":"освидетельствование на состояние опьянения;"},{"n":"•","text":"привод."},{"n":"2","text":"Применение мер оформляется протоколом либо записью в протоколе об административном правонарушении."}]},{"n":"Статья 15.10","title":"Доставление","sub":[{"n":"1","text":"Доставление — принудительное препровождение физического лица в целях составления протокола при невозможности его составления на месте."},{"n":"2","text":"Доставление должно быть осуществлено в возможно короткий срок. О доставлении составляется протокол либо делается запись в протоколе."}]},{"n":"Статья 15.11","title":"Личный досмотр, досмотр вещей и транспортного средства","sub":[{"n":"1","text":"Личный досмотр, досмотр вещей и транспортного средства осуществляются для обнаружения орудий или предметов правонарушения."},{"n":"2","text":"Личный досмотр производится лицом одного пола с досматриваемым в присутствии двух понятых того же пола."},{"n":"3","text":"О досмотре составляется протокол с указанием даты, места, сведений о досматриваемом, виде и количестве изъятых вещей."}]},{"n":"Статья 15.12","title":"Изъятие документов и предметов","sub":[{"n":"1","text":"Документы и предметы, имеющие значение по делу, изымаются уполномоченными должностными лицами."},{"n":"2","text":"Об изъятии составляется протокол либо делается запись в протоколе об административном правонарушении."},{"n":"3","text":"Изъятые документы и предметы хранятся в местах, определяемых органом или должностным лицом, в производстве которых находится дело."}]},{"n":"Статья 15.13","title":"Освидетельствование на состояние опьянения","sub":[{"n":"1","text":"Освидетельствование на состояние алкогольного опьянения и оформление его результатов осуществляются в порядке, установленном законодательством."},{"n":"2","text":"Освидетельствование на состояние наркотического или токсического опьянения проводится в медицинских организациях."},{"n":"3","text":"Акт освидетельствования приобщается к протоколу."}]},{"n":"Статья 15.14","title":"Рассмотрение дела об административном правонарушении","sub":[{"n":"1","text":"Дело рассматривается по месту совершения правонарушения либо по месту нахождения органа, в который поступило дело."},{"n":"2","text":"Дело рассматривается в срок не позднее пятнадцати суток со дня поступления протокола и материалов дела."},{"n":"3","text":"Дело рассматривается с участием лица, в отношении которого ведётся производство, либо его защитника. В отсутствие указанных лиц дело может быть рассмотрено только при наличии данных о своевременном извещении и отсутствии ходатайства об отложении."}]},{"n":"Статья 15.15","title":"Постановление по делу об административном правонарушении","sub":[{"n":"1","text":"По результатам рассмотрения выносится постановление:"},{"n":"•","text":"о назначении административного наказания;"},{"n":"•","text":"о прекращении производства по делу."},{"n":"•","text":"Постановление должно содержать:"},{"n":"•","text":"должность, фамилию и инициалы вынесшего;"},{"n":"•","text":"сведения о лице, в отношении которого рассмотрено дело;"},{"n":"•","text":"обстоятельства, установленные при рассмотрении;"},{"n":"•","text":"статью настоящего Кодекса;"},{"n":"•","text":"вид и размер назначенного наказания;"},{"n":"•","text":"порядок и срок обжалования."},{"n":"2","text":"Постановление объявляется немедленно. Копия вручается лицу под расписку либо направляется в течение трёх дней."}]},{"n":"Статья 15.16","title":"Обжалование постановления по делу","sub":[{"n":"1","text":"Постановление может быть обжаловано:"},{"n":"•","text":"лицом, в отношении которого оно вынесено;"},{"n":"•","text":"потерпевшим;"},{"n":"•","text":"законными представителями;"},{"n":"•","text":"защитником и представителем."},{"n":"2","text":"Постановление судьи обжалуется в вышестоящий суд. Постановление должностного лица — вышестоящему должностному лицу либо в суд."},{"n":"3","text":"Жалоба подаётся в течение десяти суток со дня вручения или получения копии постановления."}]},{"n":"Статья 15.17","title":"Решение по жалобе на постановление","sub":[{"n":"1","text":"По результатам рассмотрения жалобы выносится одно из решений:"},{"n":"•","text":"об оставлении постановления без изменения, жалобы — без удовлетворения;"},{"n":"•","text":"об изменении постановления, если не усиливается наказание;"},{"n":"•","text":"об отмене постановления и прекращении производства;"},{"n":"•","text":"об отмене постановления и возвращении дела на новое рассмотрение;"},{"n":"•","text":"об отмене постановления и направлении дела по подведомственности."},{"n":"2","text":"Решение вступает в законную силу немедленно."}]},{"n":"Статья 15.18","title":"Вступление постановления в законную силу и исполнение наказания","sub":[{"n":"1","text":"Постановление вступает в законную силу:"},{"n":"•","text":"по истечении десяти суток со дня вручения или получения копии, если не обжаловано;"},{"n":"•","text":"немедленно после вынесения решения по жалобе, если постановление не отменено."},{"n":"•","text":"Постановление обязательно для исполнения всеми органами, организациями и должностными лицами."},{"n":"•","text":"Штраф подлежит уплате не позднее шестидесяти дней со дня вступления постановления в силу."},{"n":"•","text":"Арест отбывается в специальных учреждениях органа внутренних дел."},{"n":"2","text":"Конфискация исполняется путём принудительного изъятия и обращения в собственность государства."}]},{"n":"Статья 15.19","title":"Сроки давности привлечения к административной ответственности","sub":[{"n":"1","text":"Постановление не может быть вынесено по истечении двух месяцев со дня совершения правонарушения."},{"n":"2","text":"При длящемся правонарушении сроки давности исчисляются со дня его обнаружения."},{"n":"3","text":"При отказе в возбуждении уголовного дела либо его прекращении сроки давности исчисляются со дня принятия соответствующего решения."}]},{"n":"Статья 15.20","title":"Возмещение расходов по делу","sub":[{"n":"1","text":"Издержки по делу состоят из:"},{"n":"•","text":"сумм, выплачиваемых свидетелям, потерпевшим, экспертам, специалистам, переводчикам;"},{"n":"•","text":"сумм, израсходованных на хранение, перевозку и исследование вещественных доказательств;"},{"n":"•","text":"иных расходов, связанных с производством."},{"n":"2","text":"Издержки по делу физического лица относятся на счёт федерального бюджета, по делу юридического лица — на счёт юридического лица."}]},{"n":"Статья 15.21","title":"Обязательность исполнения процессуальных норм","sub":[{"n":"1","text":"Настоящая глава определяет единый порядок производства по всем делам об административных правонарушениях, предусмотренных настоящим Кодексом."},{"n":"2","text":"Нарушение процессуальных норм, допущенное при производстве по делу, влечёт признание вынесенного постановления незаконным и его отмену."}]}]};
